  )(
    { tabs: { create() {}, update() {} } },
    async () => {},
    () => new Promise((resolve) => sleepResolvers.push(resolve)),
    async (tabId) => thumbnails[tabId] ?? null,
    async (tabId) => Boolean(refreshNeeded[tabId]),
    async (tabId, windowId, generation, attempts) => {
