export function createTabCard(tab, thumbnail) {
  const card = document.createElement("div");
  card.className = "tab-card";
  card.tabIndex = 0;
  card.dataset.tabId = tab.id;
  card.dataset.tabUrl = tab.url || "";
  card.draggable = true;

  let activeThumbnail = thumbnail;
  if (activeThumbnail) {
    const img = document.createElement("img");
    img.className = "card-thumbnail";
    img.src = activeThumbnail;
    img.alt = "";
    let loadRetries = 0;
    img.onerror = () => {
      if (loadRetries === 0) {
        loadRetries += 1;
        const retrySource = img.src;
        img.removeAttribute("src");
        setTimeout(() => {
          img.src = retrySource;
        }, 150);
        return;
      }

      img.onerror = null;
      activeThumbnail = null;
      console.warn("[Meridian] Cached thumbnail failed to load", {
        tabId: tab.id,
      });
      img.replaceWith(makeThumbnailPlaceholder(tab));
      chrome.runtime.sendMessage({
        type: "MARK_THUMBNAIL_REFRESH_NEEDED",
        tabId: tab.id,
      }).catch((error) => {
        console.warn(
          "[Meridian] Failed to mark thumbnail for refresh:",
          error.message,
        );
      });
    };
    card.appendChild(img);
  } else {
    card.appendChild(makeThumbnailPlaceholder(tab));
  }

  const info = document.createElement("div");
  info.className = "card-info";

  if (tab.favIconUrl) {
    const favicon = document.createElement("img");
    favicon.className = "card-favicon";
    favicon.src = tab.favIconUrl;
    favicon.alt = "";
    favicon.onerror = () => favicon.replaceWith(makeFaviconPlaceholder(tab.url, 14));
    info.appendChild(favicon);
  }

  const title = document.createElement("span");
  title.className = "card-title";
  title.textContent = tab.title || tab.url || "New Tab";
  info.appendChild(title);

  card.appendChild(info);

  const closeBtn = document.createElement("button");
  closeBtn.className = "card-close-btn";
  closeBtn.textContent = "×";
  closeBtn.setAttribute("aria-label", "Close tab");

import assert from "node:assert/strict";
import test from "node:test";

import {
  deleteThumbnailBlobs,
  getAllThumbnailBlobs,
  getAllThumbnailDisplayUrls,
  getThumbnailBlob,
  saveThumbnailBlob,
  thumbnailDataUrlToBlob,
} from "../utils/thumbnailBlobStore.js";

function installFakeIndexedDb() {
  const values = new Map();
  globalThis.indexedDB = {
    open() {
      const openRequest = {};
      queueMicrotask(() => {
        openRequest.result = {
          objectStoreNames: { contains: () => true },
          createObjectStore() {},
          close() {},
          transaction() {
            return {
              objectStore() {
                const request = (value) => {
                  const result = {};
                  queueMicrotask(() => {
                    result.result = value();
                    result.onsuccess?.();
                  });
                  return result;
                };
                return {
                  get: (key) => request(() => values.get(key)),
                  getAll: () => request(() => [...values.values()]),
                  getAllKeys: () => request(() => [...values.keys()]),
                  put(value, key) {
                    values.set(key, value);
                  },
                  add(value, key) {
                    const result = {};
                    queueMicrotask(() => {
                      if (values.has(key)) {
                        result.error = new Error("ConstraintError");
                        result.onerror?.();
                        return;
                      }
                      values.set(key, value);
                      result.onsuccess?.();
                    });
                    return result;
                  },
                  delete(key) {
                    values.delete(key);
                  },
                };
              },
              set oncomplete(callback) {
                queueMicrotask(callback);
              },
              set onerror(_callback) {},
              set onabort(_callback) {},
            };
          },
        };
        openRequest.onsuccess?.();
      });
      return openRequest;
    },
  };
  return values;
}

test("thumbnail blob storage validates and preserves encoded image bytes", async () => {
  const blob = await thumbnailDataUrlToBlob(
    "data:image/png;base64,iVBORw0KGgo=",
  );

  assert.equal(blob.type, "image/png");
  assert.ok(blob.size > 0);
});

test("thumbnail blob storage rejects non-image and empty values", async () => {
  await assert.rejects(
    thumbnailDataUrlToBlob("not-an-image"),
    /image data URL/,
  );
  await assert.rejects(
    thumbnailDataUrlToBlob("data:text/plain;base64,dGV4dA=="),
    /image data URL/,
  );
});

test("thumbnail blobs round-trip through IndexedDB and expose reusable display URLs", async () => {
  installFakeIndexedDb();
  const dataUrl = "data:image/png;base64,iVBORw0KGgo=";

  await saveThumbnailBlob(7, dataUrl, "https://example.test");
  const stored = await getThumbnailBlob(7);
  assert.equal(stored.tabUrl, "https://example.test");
  assert.equal(stored.blob.type, "image/png");

  const records = await getAllThumbnailBlobs();
  assert.equal(records.length, 1);
  assert.equal(records[0].tabId, "7");

  const firstUrls = await getAllThumbnailDisplayUrls();
  const secondUrls = await getAllThumbnailDisplayUrls();
  assert.match(firstUrls["7"], /^blob:/);
  assert.equal(secondUrls["7"], firstUrls["7"]);

  await deleteThumbnailBlobs([7]);
  assert.equal(await getThumbnailBlob(7), null);
  assert.deepEqual(await getAllThumbnailDisplayUrls(), {});
});
