--- sidebar search CSS ---
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 13px;
  color: CanvasText;
  background: Canvas;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

#sidebar-wrap {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* ---- Search ---- */

#search-zone {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border-bottom: 1px solid color-mix(in srgb, CanvasText 10%, transparent);
  flex-shrink: 0;
}

#meridian-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 4px;
  border: none;
  background: none;
  cursor: pointer;
  border-radius: 4px;
  opacity: 0.7;
  transition: opacity 80ms ease, background 80ms ease;
}

#meridian-btn:hover {
  background: color-mix(in srgb, CanvasText 8%, transparent);
  opacity: 1;
}

#sidebar-logo {
  display: block;
}

#search-input {
  flex: 1;
  padding: 6px 10px;
  border: 1px solid color-mix(in srgb, CanvasText 20%, transparent);
  border-radius: 6px;
  background: Field;
  color: FieldText;
  font-size: 13px;
  font-family: inherit;
  outline: none;
}

#search-input::placeholder {
  color: GrayText;
}

/* ---- Tab list ---- */

#tab-list {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, CanvasText 20%, transparent) transparent;
}

#tab-list::-webkit-scrollbar {
  width: 4px;
}

#tab-list::-webkit-scrollbar-track {
  background: transparent;
}

#tab-list::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, CanvasText 20%, transparent);
  border-radius: 2px;
