// ---------------------------------------------------------------------------
// Narrow mode (icon-only when panel is very narrow)
// ---------------------------------------------------------------------------

function setupResizeObserver() {
  const ro = new ResizeObserver(([entry]) => {
    document.body.classList.toggle('narrow', entry.contentRect.width < 64);
  });
  ro.observe(document.body);
}

