      getElementById(id) {
        if (id === "search-input") return input;
        if (id === "search-clear-btn") return clearButton;
        if (id === "tab-list") return container;
        return button;
      },
      querySelector() {
        return null;
      },
    },
    {
      storage: {
        sync: {
          get(key) {
            if (key === "searchProvider") return pendingProvider.promise;
