          },
        },
        local: { get: async () => ({}) },
      },
      tabs: { create() {} },
    },
    async () => ({ tabs: true, bookmarks: true, history: true }),
    (query) => {
      const request = deferred();
      pendingSearches.set(query, request);
      return request.promise;
    },
    (_container, label, items) => {
      if (items.length) writes.push(["section", label, items[0].title]);
    },
    () => writes.push(["tabs"]),
